from pydantic import BaseModel, Field
from pydantic import AliasChoice
import pytest

def test_validation_alias():
    app = FastAPI()
    class Item(BaseModel):
        name: str = Field(validation_alias="item_name")
    @app.get("/items/")
    async def read_items(item: Item = Depends()):
        return item
    client = TestClient(app)
    response = client.get("/items/?item_name=foo")
    assert response.status_code == 200
    assert response.json() == {"name": "foo"}

def test_alias():
    app = FastAPI()
    class Item(BaseModel):
        name: str = Field(alias="item_name")
    @app.get("/items/")
    async def read_items(item: Item = Depends()):
        return item
    client = TestClient(app)
    response = client.get("/items/?item_name=foo")
    assert response.status_code == 200
    assert response.json() == {"name": "foo"}

def test_no_alias():
    app = FastAPI()
    class Item(BaseModel):
        name: str
    @app.get("/items/")
    async def read_items(item: Item = Depends()):
        return item
    client = TestClient(app)
    response = client.get("/items/?name=foo")
    assert response.status_code == 200
    assert response.json() == {"name": "foo"}

def test_validation_alias_non_string():
    app = FastAPI()
    class Item(BaseModel):
        name: str = Field(validation_alias=AliasChoice("item_name", "name"), alias="fallback_name")
    @app.get("/items/")
    async def read_items(item: Item = Depends()):
        return item
    client = TestClient(app)
    # Should fall back to alias "fallback_name" because validation_alias is not a string
    response = client.get("/items/?fallback_name=foo")
    assert response.status_code == 200
    assert response.json() == {"name": "foo"}

if __name__ == "__main__":
    try:
        test_validation_alias()
        print("test_validation_alias passed!")
        test_alias()
        print("test_alias passed!")
        test_no_alias()
        print("test_no_alias passed!")
        test_validation_alias_non_string()
        print("test_validation_alias_non_string passed!")
        print("All tests passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        raise e
